css:
/* Build and Execute (Operating System), from proposal/os-v2/roadmap-studio.html: the reference styles, design tokens unchanged.
   Inside SKL OS the module lives in a shadow root (:host) under the SKL OS sidebar, so the reference's own left navigation is gone. */
:host{
  --bg:#F6F4EF;--card:#FFFFFF;--ink:#1B1B18;--ink2:#3D3A33;--mut:#5E5B53;--mut2:#8C877B;--line:#E3DFD5;--line2:#EEEBE4;--soft:#ECE8DF;
  --gold:#D9B46A;--gold2:#9A6614;--goldsoft:#FBF6EC;--goldline:#E6D3A8;
  --ok:#2E7D4F;--oks:#E6F2EA;--late:#B45309;--lates:#FEF3E2;--crit:#C2261A;--crits:#FDECEA;--info:#2D5C9C;--infos:#E8EEF7;
  --pbg:#1B1B18;--pfg:#D9B46A;--shadow:0 1px 2px rgba(27,27,24,.05);
  --serif:Fraunces,Georgia,serif;--sans:'IBM Plex Sans',system-ui,-apple-system,'Segoe UI',sans-serif;--mono:'IBM Plex Mono',ui-monospace,Menlo,monospace;
  color-scheme:light}
*{box-sizing:border-box}
[hidden]{display:none!important}
.os2{background:var(--bg);color:var(--ink);font-family:var(--sans);font-size:14px;line-height:1.45;-webkit-font-smoothing:antialiased;
  container-type:inline-size;display:flex;flex-direction:column;gap:18px}
button,input,select,textarea{font:inherit;color:inherit}
button{cursor:pointer}
:focus-visible{outline:2px solid var(--gold);outline-offset:2px}
.mono{font-family:var(--mono);font-variant-numeric:tabular-nums}
.wrap{max-width:1720px;margin:0 auto;display:grid;grid-template-columns:184px minmax(0,1fr);gap:22px;align-items:start}
.mainc{display:flex;flex-direction:column;gap:18px;padding-top:18px;min-width:0}
.snav{position:sticky;top:env(safe-area-inset-top,0px);height:100vh;display:flex;flex-direction:column;gap:22px;padding:22px 16px 22px 0;border-right:1px solid var(--line);z-index:8;background:var(--bg)}
.snl{display:flex;flex-direction:column;gap:4px}
.snl button{display:flex;align-items:center;gap:10px;border:0;background:none;border-radius:10px;padding:10px 12px;font-size:14.5px;font-weight:500;color:var(--ink2);text-align:left}
.snl button svg{width:16px;height:16px;flex-shrink:0}
.snl button:hover{background:var(--soft)}
.snl button[aria-pressed="true"]{background:var(--ink);color:var(--bg);font-weight:600}
.snav .ibtn{align-self:flex-start}

/* top bar */
.top{position:sticky;top:env(safe-area-inset-top,0px);z-index:8;background:var(--bg);display:flex;align-items:center;gap:14px;flex-wrap:wrap;padding:14px 0 12px;border-bottom:1px solid var(--line)}
.brand{display:flex;flex-direction:column;line-height:1.15;margin-right:6px}
.brand b{font-family:var(--serif);font-weight:500;font-size:20px}
.brand span{font-size:11px;letter-spacing:.12em;text-transform:uppercase;color:var(--gold2);font-weight:700}
.seg{display:flex;gap:4px;padding:4px;background:var(--soft);border-radius:12px}
.seg button{border:0;background:none;border-radius:9px;padding:8px 16px;font-size:14px;font-weight:500;color:var(--ink2);display:flex;gap:7px;align-items:center}
.seg button[aria-pressed="true"]{background:var(--ink);color:var(--bg);font-weight:600}
.seg button small{font-size:11px;opacity:.7;font-weight:500}
.sp{flex:1}
.krsel{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--mut)}
.krsel{min-width:0;max-width:100%}.krsel select{min-height:38px;max-width:min(360px,calc(100vw - 120px));min-width:0;border:1px solid var(--line);border-radius:10px;background:var(--card);padding:0 10px;font-size:13px;color:var(--ink)}
.ibtn{width:38px;height:38px;border-radius:50%;border:1px solid var(--line);background:var(--card);font-family:var(--serif);font-style:italic;font-weight:600;font-size:17px}
.btn{min-height:36px;padding:0 14px;border-radius:10px;border:1px solid var(--line);background:var(--card);font-size:13px;font-weight:600;white-space:nowrap;display:inline-flex;align-items:center;gap:7px}
.btn.p{background:var(--pbg);color:var(--pfg);border-color:var(--pbg)}
.btn.sm{min-height:30px;padding:0 10px;font-size:12.5px}
.btn.ghost{border-color:transparent;background:none;color:var(--gold2)}
.btn:disabled{opacity:.45;cursor:not-allowed}
.pk{font-size:11px;letter-spacing:.1em;text-transform:uppercase;color:var(--mut2);font-weight:700}
.card{background:var(--card);border:1px solid var(--line);border-radius:14px;box-shadow:var(--shadow)}

/* build grid */
.build{display:grid;grid-template-columns:270px minmax(0,1fr) 420px;gap:18px;align-items:start}
.build>*{min-width:0}
.rail{position:sticky;top:18px;display:flex;flex-direction:column;gap:14px;max-height:calc(100vh - 36px);overflow-y:auto;padding-bottom:2px}
.steps{padding:8px}
.step{display:grid;grid-template-columns:26px 1fr auto;gap:10px;align-items:center;width:100%;text-align:left;border:0;background:none;border-radius:10px;padding:9px 8px}
.step:hover{background:var(--goldsoft)}
.step[aria-current="true"]{background:var(--soft)}
.step .n{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;font:600 12px var(--mono);border:1.5px solid var(--line);color:var(--mut)}
.step.ok .n{background:var(--ok);border-color:var(--ok);color:#fff}
.step[aria-current="true"] .n{border-color:var(--ink);color:var(--ink)}
.step b{display:block;font-size:13.5px;font-weight:600}
.step span.d{display:block;font-size:11.5px;color:var(--mut)}
.badge{font:600 11px/18px var(--mono);padding:0 7px;border-radius:999px;background:var(--crits);color:var(--crit)}
.badge.ok{background:var(--oks);color:var(--ok)}
.score{padding:12px 14px;display:flex;flex-direction:column;gap:8px}
.qrow{display:flex;align-items:baseline;justify-content:space-between;gap:8px}.qrow b{font-family:var(--serif);font-size:30px;font-weight:500;line-height:1}.qrow small{font-size:15px}
.qbar{height:6px;border-radius:3px;background:var(--soft);overflow:hidden}.qbar i{display:block;height:100%;border-radius:3px}
.ring{display:flex;gap:14px;align-items:center}
.ring svg{flex-shrink:0}
.ring b{font-family:var(--serif);font-size:30px;font-weight:500;line-height:1}
.ring span{font-size:12px;color:var(--mut)}
.kv{display:grid;grid-template-columns:1fr auto;gap:6px 10px;font-size:12.5px}
.kv span{color:var(--mut)}.kv b{font-family:var(--mono);font-weight:600}

/* workspace */
.ws{display:flex;flex-direction:column;gap:16px}
.wsh{display:flex;align-items:flex-end;justify-content:space-between;gap:14px;flex-wrap:wrap}
.wsh h1{margin:0;font-family:var(--serif);font-weight:500;font-size:30px;letter-spacing:-.01em;text-wrap:balance}
.wsh p{margin:4px 0 0;color:var(--mut);font-size:13.5px;max-width:68ch}
.rule{display:flex;gap:10px;align-items:flex-start;background:var(--goldsoft);border:1px solid var(--goldline);border-radius:12px;padding:10px 14px;font-size:13px;color:var(--ink2)}
.rule b{color:var(--ink)}
.rule .ic{font-family:var(--serif);font-style:italic;color:var(--gold2);font-size:18px;line-height:1}
.krc{padding:18px 20px;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}
.krc .full{grid-column:1/-1}
.fld{display:flex;flex-direction:column;gap:5px;font-size:12px;color:var(--mut)}
.fld input,.fld select,.fld textarea{min-height:38px;border:1px solid var(--line);border-radius:10px;background:var(--card);padding:6px 10px;font-size:14px;color:var(--ink);width:100%}
.fld textarea{min-height:60px;resize:vertical;line-height:1.4}
.fld .v{font:600 18px var(--mono);color:var(--ink)}
.checks{display:flex;flex-wrap:wrap;gap:6px}
.chk{display:inline-flex;align-items:center;gap:5px;font-size:11.5px;font-weight:600;padding:2px 8px;border-radius:999px;background:var(--oks);color:var(--ok)}
.chk.x{background:var(--crits);color:var(--crit)}
.chk.w{background:var(--lates);color:var(--late)}

.ms{overflow:hidden}
.msh{display:grid;grid-template-columns:42px minmax(0,1fr) auto;gap:12px;padding:14px 16px;align-items:start}
.msn{width:42px;height:42px;border-radius:10px;background:var(--soft);display:flex;flex-direction:column;align-items:center;justify-content:center;font:600 11px/1.1 var(--mono);color:var(--mut)}
.msn b{font-size:14px;color:var(--ink)}
.ti{width:100%;border:1px solid transparent;border-radius:8px;background:none;padding:4px 6px;margin-left:-6px;font-family:var(--serif);font-size:17px;font-weight:500;color:var(--ink);line-height:1.3;resize:none;overflow:hidden}
.ti:hover{border-color:var(--line)}.ti:focus{border-color:var(--gold);background:var(--card);outline:none}
.meta{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin-top:6px}
.meta select,.meta input{min-height:30px;border:1px solid var(--line);border-radius:8px;background:var(--card);padding:0 8px;font-size:12.5px;color:var(--ink)}
.meta input.num{width:70px;font-family:var(--mono)}
.proof{padding:0 16px 12px 70px;display:flex;flex-direction:column;gap:5px}
.proof .pr{display:flex;gap:8px;align-items:center}
.proof input{flex:1;min-width:0;min-height:32px;border:1px solid var(--line);border-radius:8px;background:var(--card);padding:0 9px;font-size:13px}
button.x:not(.chk){border:0;background:none;color:var(--mut2);font-size:16px;width:28px;height:28px;border-radius:6px;flex-shrink:0}
button.x:not(.chk):hover{background:var(--crits);color:var(--crit)}
.tasks{border-top:1px solid var(--line2);background:color-mix(in srgb,var(--soft) 35%,var(--card))}
.trow{display:grid;grid-template-columns:minmax(0,2.2fr) minmax(0,2fr) 120px 74px 28px;gap:8px;align-items:start;padding:9px 16px 9px 70px;border-bottom:1px solid var(--line2)}
.trow:last-child{border-bottom:0}
.trow input,.trow select{width:100%;min-height:32px;border:1px solid var(--line);border-radius:8px;background:var(--card);padding:0 8px;font-size:13px;color:var(--ink)}
.trow input.num{font-family:var(--mono)}
.trow .checks{grid-column:1/-1}
.thead{padding:8px 16px 4px 70px;display:grid;grid-template-columns:minmax(0,2.2fr) minmax(0,2fr) 120px 74px 28px;gap:8px;font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--mut2);font-weight:700}
.addrow{padding:8px 16px 12px 70px}
.empty{padding:28px;text-align:center;color:var(--mut)}

table.t{width:100%;border-collapse:collapse;font-size:13px}
table.t th{text-align:left;font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--mut2);font-weight:700;padding:10px 12px;border-bottom:1px solid var(--line)}
table.t td{padding:10px 12px;border-bottom:1px solid var(--line2);vertical-align:middle}
table.t tr:last-child td{border-bottom:0}
table.t td.n{font-family:var(--mono);font-variant-numeric:tabular-nums;white-space:nowrap}
table.t input.num{width:64px;min-height:30px;border:1px solid var(--line);border-radius:8px;background:var(--card);padding:0 8px;font-family:var(--mono);font-size:13px;color:var(--ink)}
.tw{overflow-x:auto}
.who{display:inline-flex;align-items:center;gap:6px;white-space:nowrap}
.av{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;font-size:9.5px;font-weight:700;color:#fff;flex-shrink:0}

.fc{padding:18px 20px;display:flex;flex-direction:column;gap:14px}
.fchead{display:flex;gap:24px;align-items:center;flex-wrap:wrap}
.big{font-family:var(--serif);font-size:48px;line-height:1;font-weight:500;letter-spacing:-.02em}
.verdict{display:inline-flex;align-items:center;gap:6px;font-size:12px;font-weight:700;padding:3px 10px;border-radius:999px}
.verdict.ok{background:var(--oks);color:var(--ok)}.verdict.w{background:var(--lates);color:var(--late)}.verdict.x{background:var(--crits);color:var(--crit)}
svg.ch{width:100%;height:auto;display:block;overflow:visible}
svg.ch text{font-family:var(--sans);font-size:11px;fill:var(--mut)}
svg.ch text.l{fill:var(--ink);font-size:12px;font-weight:600}
svg.ch text.v{font-family:var(--mono);fill:var(--ink);font-weight:600}
.lg{display:flex;gap:16px;flex-wrap:wrap;font-size:12px;color:var(--mut)}
.lg span{display:inline-flex;gap:6px;align-items:center}.lg i{display:inline-block}
.risk{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) 120px 28px;gap:8px;padding:8px 16px 8px 70px;border-bottom:1px solid var(--line2);align-items:center}
.risk input,.risk select{width:100%;min-height:32px;border:1px solid var(--line);border-radius:8px;background:var(--card);padding:0 8px;font-size:13px;color:var(--ink)}

/* Claude guide */
.col3{position:sticky;top:18px;display:flex;flex-direction:column;gap:14px;height:calc(100vh - 170px);min-height:420px;min-width:0}
.guide{display:flex;flex-direction:column;overflow:hidden;flex:1 1 auto;min-height:0}
.gh{padding:14px 16px 10px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:10px}
.gh .mk{width:30px;height:30px;border-radius:9px;background:var(--pbg);color:var(--pfg);display:grid;place-items:center;font-family:var(--serif);font-weight:600;font-size:16px}
.gh b{display:block;font-size:14px}.gh span{display:block;font-size:11.5px;color:var(--mut)}
.feed{flex:1;overflow-y:auto;padding:12px 14px;display:flex;flex-direction:column;gap:10px;min-height:80px}
.gh,.gin,.status{flex-shrink:0}
.msg{font-size:13.5px;line-height:1.5;color:var(--ink2);white-space:pre-wrap}
.msg.me{align-self:flex-end;background:var(--soft);border-radius:12px 12px 4px 12px;padding:8px 12px;max-width:88%;color:var(--ink)}
.msg.cl{border-left:2px solid var(--gold);padding-left:10px}
.msg.sys{font-size:12px;color:var(--mut);text-align:center}
.sug{border:1px solid var(--goldline);background:var(--goldsoft);border-radius:12px;padding:10px 12px;display:flex;flex-direction:column;gap:6px}
.sug .ty{font-size:10.5px;letter-spacing:.09em;text-transform:uppercase;color:var(--gold2);font-weight:700}
.sug b{font-size:13.5px;font-weight:600;color:var(--ink)}
.sug p{margin:0;font-size:12.5px;color:var(--ink2)}
.sug .pv{font-size:12.5px;color:var(--ink);background:var(--card);border:1px solid var(--line);border-radius:8px;padding:6px 9px}
.sug .acts{display:flex;gap:6px}
.sug.done{opacity:.55}.sug.done .acts{display:none}
.gq{display:flex;flex-wrap:wrap;gap:6px;padding:8px 14px;border-top:1px solid var(--line2);max-height:120px;overflow-y:auto;flex-shrink:0}
.gql{width:100%;font-size:10.5px;letter-spacing:.09em;text-transform:uppercase;color:var(--mut2);font-weight:700}
.gqc{text-align:left;display:inline-flex;gap:6px;align-items:baseline;line-height:1.3}
.gqk{font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--gold2);white-space:nowrap}
.chip{border:1px solid var(--line);background:var(--card);border-radius:999px;padding:5px 11px;font-size:12.5px;color:var(--ink2)}
.chip:hover{border-color:var(--gold)}
.gin{border-top:1px solid var(--line);padding:10px 12px;display:flex;gap:8px;align-items:flex-end}
.gin textarea{flex:1;min-width:0;min-height:40px;max-height:120px;resize:vertical;border:1px solid var(--line);border-radius:10px;background:var(--card);padding:8px 10px;font-size:13.5px;color:var(--ink)}
.status{font-size:11.5px;color:var(--mut);padding:0 14px 8px}
.dots::after{content:"";animation:dots 1.4s steps(4) infinite}
@keyframes dots{0%{content:""}25%{content:"."}50%{content:".."}75%{content:"..."}}

/* execute */
.exec{display:grid;grid-template-columns:minmax(0,1fr) 320px;gap:18px;align-items:start}
.exec>*{min-width:0}
.ehead{display:flex;gap:14px;align-items:center;flex-wrap:wrap}
.prog{flex:1;min-width:200px}
.prog .bar{height:8px;border-radius:4px;background:var(--soft);overflow:hidden;margin-top:6px}
.prog .bar i{display:block;height:100%;background:var(--ink);border-radius:4px}
.stage{display:flex;flex-direction:column;align-items:center;gap:16px;padding:20px 0}
.deck{position:relative;width:min(560px,100%)}
.deck::before,.deck::after{content:"";position:absolute;left:16px;right:16px;bottom:-8px;height:20px;border-radius:0 0 18px 18px;background:var(--card);border:1px solid var(--line);z-index:0}
.deck::after{left:32px;right:32px;bottom:-16px;opacity:.6}
.tc{position:relative;z-index:1;background:var(--card);border:1px solid var(--line);border-radius:18px;padding:24px 26px;display:flex;flex-direction:column;gap:14px;box-shadow:0 12px 32px rgba(27,27,24,.08);transition:transform .25s ease,opacity .25s ease}
.tc.out{transform:translateX(60px) rotate(4deg);opacity:0}
@media (prefers-reduced-motion:reduce){.tc{transition:none}}
.tc .ctx{display:flex;gap:8px;flex-wrap:wrap;align-items:center;font-size:12px;color:var(--mut)}
.tag{font-size:11px;font-weight:700;padding:2px 9px;border-radius:999px;background:var(--soft);color:var(--ink2)}
.tc h2{margin:0;font-family:var(--serif);font-weight:500;font-size:28px;line-height:1.2;text-wrap:balance}
.dw{display:flex;gap:10px;font-size:14px;color:var(--ink2);background:var(--soft);border-radius:10px;padding:10px 12px}
.dw b{color:var(--ink)}
.est{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
.est div{display:flex;flex-direction:column;gap:2px;border-left:2px solid var(--line);padding-left:10px}
.est b{font:600 20px var(--mono)}.est span{font-size:11.5px;color:var(--mut)}
.why{font-size:12.5px;color:var(--mut)}
.timer{font:600 40px var(--mono);text-align:center;letter-spacing:.02em}
.cacts{display:flex;gap:8px;flex-wrap:wrap;justify-content:center}
.cacts .btn{min-height:44px;padding:0 18px;font-size:14px}
.side{display:flex;flex-direction:column;gap:14px}
.side .card{padding:14px 16px;display:flex;flex-direction:column;gap:8px}
.li{display:flex;justify-content:space-between;gap:8px;font-size:13px;padding:5px 0;border-bottom:1px solid var(--line2)}
.li:last-child{border-bottom:0}
.li span{color:var(--mut)}
.help{border:1px solid var(--info);background:var(--infos);border-radius:18px;padding:20px 22px;display:flex;flex-direction:column;gap:12px;width:min(560px,100%)}
.help h3{margin:0;font-family:var(--serif);font-weight:500;font-size:22px}
.reasons{display:flex;flex-wrap:wrap;gap:6px}
.reasons button[aria-pressed="true"]{background:var(--ink);color:var(--bg);border-color:var(--ink)}
.cockpit{padding:24px;display:flex;flex-direction:column;gap:12px;max-width:760px}
.cockpit h2{margin:0;font-family:var(--serif);font-weight:500;font-size:26px}
.cockpit ul{margin:0;padding-left:20px;display:flex;flex-direction:column;gap:6px;color:var(--ink2)}

/* execute: day setup, run, replan */
.xwrap{display:flex;flex-direction:column;gap:14px;max-width:1080px;margin:0 auto;width:100%}
.xwin{padding:20px 22px;display:flex;flex-direction:column;gap:18px}
.xhead{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;flex-wrap:wrap}
.xhead h2{margin:2px 0 0;font-family:var(--serif);font-weight:500;font-size:28px;line-height:1.15}
.xsec{display:flex;flex-direction:column;gap:10px}
.xsh{display:flex;align-items:center;gap:12px;flex-wrap:wrap}
.xsh h3{margin:0;font-size:15px;font-weight:700}
.xsub{display:flex;flex-direction:column;gap:6px;margin-top:4px}
.olist{display:flex;flex-wrap:wrap;gap:8px}
.ochip{display:inline-flex;align-items:center;gap:9px;text-align:left;border:1px solid var(--line);background:var(--card);border-radius:12px;padding:8px 12px;font-size:13.5px;color:var(--ink2);max-width:100%}
.ochip .ob{width:22px;height:22px;border-radius:50%;border:1.5px solid var(--line);display:grid;place-items:center;font:600 11px var(--mono);flex-shrink:0}
.ochip[aria-pressed="true"]{border-color:var(--ink);background:var(--goldsoft);color:var(--ink);font-weight:600}
.ochip[aria-pressed="true"] .ob{background:var(--ink);border-color:var(--ink);color:var(--bg)}
.ochip .src{font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--gold2);white-space:nowrap}
.oadd{display:flex;gap:8px}
.oadd input,.inp{flex:1;min-width:0;min-height:38px;border:1px solid var(--line);border-radius:10px;background:var(--card);padding:0 12px;font-size:14px;color:var(--ink)}
.road{list-style:none;margin:0;padding:0;display:flex;flex-direction:column}
.rrow{--tl:58px;display:grid;grid-template-columns:var(--tl) 14px minmax(0,1fr) auto auto;gap:12px;align-items:start;padding:10px 0;position:relative}
.rrow::before{content:"";position:absolute;left:calc(var(--tl) + 18px);top:0;bottom:0;width:2px;background:var(--line)}
.rrow:first-child::before{top:18px}.rrow:last-child::before{bottom:calc(100% - 18px)}
.rt{font-size:13px;font-weight:600;text-align:right;line-height:1.25;display:flex;flex-direction:column}.rt small{font-weight:400;color:var(--mut);font-size:11.5px}
.rdot{width:14px;height:14px;border-radius:50%;background:var(--ink);border:3px solid var(--card);box-shadow:0 0 0 1px var(--line);margin-top:2px;position:relative;z-index:1}
.rdot.other{background:var(--gold)}.rdot.help{background:var(--info)}
.rbody{display:flex;flex-direction:column;gap:3px}.rbody b{font-size:14.5px;font-weight:600}
.rh{font-size:13px;font-weight:600;padding-top:2px}
.racts{display:flex;gap:2px}.racts .x:disabled{opacity:.25;cursor:default;background:none}
.mini{margin:0;padding:0;list-style:none;display:flex;flex-direction:column;gap:6px}
.mini li{display:flex;gap:10px;align-items:center;justify-content:space-between;flex-wrap:wrap;font-size:13px;padding:8px 12px;border:1px dashed var(--line);border-radius:10px}
.mini li>span:first-child{min-width:0;flex:1}
.mini li.wait{opacity:.75}
.mini li.rp{border-style:solid}
.seg.sm{padding:3px}.seg.sm button{padding:5px 10px;font-size:12.5px}
.xfoot{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;border-top:1px solid var(--line2);padding-top:14px}
.xfoot .btn{min-height:42px}
.obar{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.obj{display:flex;gap:10px;align-items:flex-start;text-align:left;border:1px solid var(--goldline);background:var(--goldsoft);border-radius:12px;padding:11px 13px;font-size:13.5px;font-weight:600;color:var(--ink);line-height:1.35}
.obj .ok{width:24px;height:24px;border-radius:50%;background:var(--ink);color:var(--bg);display:grid;place-items:center;font:600 12px var(--mono);flex-shrink:0}
.obj.done{background:var(--oks);border-color:var(--ok);color:var(--mut);text-decoration:line-through}
.obj.done .ok{background:var(--ok);color:#fff}
.frise{display:flex;gap:4px;min-width:max-content;width:100%;padding:2px}
.fb{display:flex;flex-direction:column;gap:6px;min-width:128px;flex-basis:0}
.fb .fl{font-size:12px;font-weight:600;line-height:1.25;color:var(--ink2);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;min-height:30px}
.fb .fbar{height:12px;border-radius:6px;background:var(--soft)}
.fb .ft{font:500 11px var(--mono);color:var(--mut)}
.fb.done .fbar{background:var(--ok)}.fb.done .fl{color:var(--mut)}
.fb.cur .fbar{background:var(--ink)}.fb.cur .fl{color:var(--ink)}.fb.cur .ft{color:var(--ink);font-weight:600}
.fb.blocked .fbar{background:var(--crit)}
.fb.fhelp .fbar{background:repeating-linear-gradient(45deg,var(--info) 0 4px,var(--infos) 4px 8px)}
.fb.fhelp.done .fbar{background:var(--ok)}
.xsubf{display:flex;flex-direction:column;gap:8px}.xsubf:empty{display:none}
.xclaude{display:flex;flex-direction:column;gap:8px;border:1px solid var(--goldline);background:var(--goldsoft);border-radius:12px;padding:10px 12px}
.dlg .seg{flex-wrap:wrap;align-self:flex-start}
@container (max-width:820px){.obar{grid-template-columns:1fr}.rrow{--tl:44px;grid-template-columns:var(--tl) 14px minmax(0,1fr) auto}.rrow .racts{grid-column:3/-1}.xhead h2{font-size:23px}}

/* day setup v2 */
.xwrap.wide{max-width:1380px}
.xctl{display:flex;gap:10px;flex-wrap:wrap;align-items:center}
.sn{width:24px;height:24px;border-radius:50%;background:var(--ink);color:var(--bg);display:grid;place-items:center;font:600 12px var(--mono);flex-shrink:0}
.krrow{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(340px,100%),1fr));gap:12px}
.bld>*,.xwin>*,.xsec>*{min-width:0}
.krcard{border:1px solid var(--line);border-radius:14px;padding:14px;display:flex;flex-direction:column;gap:8px;background:color-mix(in srgb,var(--soft) 30%,var(--card))}
.krt{display:flex;flex-direction:column;gap:2px}.krt b{font-family:var(--serif);font-weight:500;font-size:17px;line-height:1.3}
.msel{display:flex;gap:10px;align-items:flex-start;text-align:left;width:100%;border:1px solid var(--line);background:var(--card);border-radius:10px;padding:10px 12px}
.msel:hover{border-color:var(--gold)}
.msel.on{border-color:var(--ink);box-shadow:inset 3px 0 0 var(--gold)}
.mbox{width:20px;height:20px;border-radius:6px;border:1.5px solid var(--line);display:grid;place-items:center;font-size:12px;flex-shrink:0;margin-top:1px}
.msel.on .mbox{background:var(--ink);border-color:var(--ink);color:var(--bg)}
.mb{display:flex;flex-direction:column;gap:5px;min-width:0}.mt{font-size:13.5px;color:var(--ink2);line-height:1.35}.mt b{color:var(--ink)}
.mm{display:flex;gap:8px;align-items:center;flex-wrap:wrap;font-size:12px;color:var(--mut)}
.og{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.og3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;align-items:stretch}
.og3 .oadd{grid-column:1/-1}
.ocard{display:grid;grid-template-columns:24px 1fr;grid-template-rows:1fr auto;gap:4px 10px;text-align:left;border:1px solid var(--line);background:var(--card);border-radius:12px;padding:12px;min-height:86px;font-size:13.5px;color:var(--ink2);line-height:1.35}
.ocard:hover{border-color:var(--gold)}
.ocard .ob{grid-row:1/3;width:24px;height:24px;border-radius:50%;border:1.5px solid var(--line);display:grid;place-items:center;font:600 12px var(--mono)}
.ocard .src{font-size:10px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--gold2)}
.ocard[aria-pressed="true"]{border-color:var(--ink);background:var(--goldsoft);color:var(--ink);font-weight:600}
.ocard[aria-pressed="true"] .ob{background:var(--ink);border-color:var(--ink);color:var(--bg)}
.ocard.own{border-style:dashed}
.bld{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.2fr);gap:16px;align-items:start}
.poolc{display:flex;flex-direction:column;gap:12px;border:1px dashed var(--line);border-radius:14px;padding:12px;background:color-mix(in srgb,var(--soft) 40%,var(--card));min-height:200px}
.poolc.over{border-color:var(--gold);background:var(--goldsoft)}
.pg{display:flex;flex-direction:column;gap:6px}
.pgh{display:flex;align-items:baseline;gap:8px}.pgh b{font-size:12px;letter-spacing:.08em;text-transform:uppercase}
.cnt{margin-left:auto;font:600 11px var(--mono);color:var(--mut);background:var(--soft);border-radius:999px;padding:1px 7px}
details.pg summary{cursor:pointer;display:flex;gap:8px;align-items:baseline;font-size:12px;letter-spacing:.08em;text-transform:uppercase}
.pc{display:flex;gap:8px;align-items:center;background:var(--card);border:1px solid var(--line);border-left:3px solid var(--ink);border-radius:10px;padding:8px 8px 8px 6px;cursor:grab}
.pc:hover{border-color:var(--gold)}.pc.dragging,.tcard.dragging{opacity:.4}
.pc.request{border-left-color:var(--info)}.pc.objective{border-left-color:var(--gold)}.pc.other,.pc.extra{border-left-color:var(--mut2)}.pc.carried{border-left-color:var(--late)}
.pc.off{cursor:default;opacity:.7;border-left-color:var(--line)}
.grip{color:var(--mut2);font-size:12px;letter-spacing:-2px;padding:0 2px}
.pcb{flex:1;min-width:0;display:flex;flex-direction:column;gap:3px}.pcb b{font-size:13.5px;font-weight:600;line-height:1.3}
.pm{display:flex;gap:6px;flex-wrap:wrap;align-items:center;font-size:11.5px}
.ph{font-size:12.5px;font-weight:600;white-space:nowrap}
.pc .add{width:30px;height:30px;border-radius:8px;border:1px solid var(--line);background:var(--card);font-size:17px;line-height:1;flex-shrink:0}
.pc .add:hover{background:var(--ink);color:var(--bg);border-color:var(--ink)}
.qadd select{min-height:38px;border:1px solid var(--line);border-radius:10px;background:var(--card);padding:0 8px}
.todayc{border:1px solid var(--ink);border-radius:14px;padding:14px;display:flex;flex-direction:column;gap:10px;background:var(--card);position:sticky;top:18px}
.tdh{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.tdh b{font-family:var(--serif);font-size:20px;font-weight:500}
.capbar{display:flex;height:12px;border-radius:6px;overflow:hidden;background:var(--soft);gap:2px}
.capbar i{display:block;height:100%;background:var(--ink)}.capbar i.request,.capbar i.help{background:var(--info)}.capbar i.objective{background:var(--gold)}.capbar i.other,.capbar i.extra{background:var(--mut2)}.capbar i.unpl{background:var(--late)}
.capbar i.buf{background:repeating-linear-gradient(45deg,var(--line) 0 3px,transparent 3px 7px)}
.capl{display:flex;gap:16px;flex-wrap:wrap;font-size:12px;color:var(--mut)}.capl b{color:var(--ink)}
.cnote{display:flex;gap:8px;align-items:flex-start;font-size:13px;color:var(--ink2);background:var(--goldsoft);border:1px solid var(--goldline);border-radius:10px;padding:8px 10px}
.cnote .mk{width:22px;height:22px;border-radius:6px;background:var(--pbg);color:var(--pfg);display:grid;place-items:center;font-family:var(--serif);font-weight:600;flex-shrink:0}
.tl{list-style:none;margin:0;padding:6px;display:flex;flex-direction:column;gap:6px;min-height:120px;border-radius:12px;border:1px dashed transparent}
.tl.over{border-color:var(--gold);background:var(--goldsoft)}
.tcard{display:grid;grid-template-columns:52px minmax(0,1fr) auto auto;gap:10px;align-items:start;border:1px solid var(--line);border-left:3px solid var(--ink);border-radius:10px;padding:9px 8px 9px 10px;background:var(--card);cursor:grab}
.tcard.request,.tcard.help{border-left-color:var(--info)}.tcard.objective{border-left-color:var(--gold)}.tcard.other,.tcard.extra{border-left-color:var(--mut2)}.tcard.unpl{border-left-color:var(--late)}
.tt{font-size:12.5px;font-weight:600;display:flex;flex-direction:column;line-height:1.25}.tt small{font-weight:400;color:var(--mut);font-size:11px}
.tb{display:flex;flex-direction:column;gap:3px;min-width:0}.tb b{font-size:13.5px;font-weight:600;line-height:1.3}
.why{font-size:11.5px;color:var(--gold2);font-style:italic}
.th{display:flex;align-items:center;gap:2px;font-size:12.5px;font-weight:600;white-space:nowrap;padding-top:1px}
.lunch{font-size:11.5px;color:var(--mut);text-align:center;letter-spacing:.06em;text-transform:uppercase;padding:2px 0;border-top:1px dashed var(--line);border-bottom:1px dashed var(--line)}
.tempty{padding:30px;text-align:center;color:var(--mut);font-size:13px}
.ph-line{height:3px;border-radius:2px;background:var(--gold);list-style:none}
.ntask{display:grid;grid-template-columns:minmax(0,2fr) minmax(0,1.5fr) auto auto minmax(0,1.6fr) auto;gap:8px}
.ntask select{min-height:38px;border:1px solid var(--line);border-radius:10px;background:var(--card);padding:0 8px;min-width:0;color:var(--ink)}
.ta{min-height:58px;padding:8px 12px;resize:vertical;line-height:1.4}
.ugrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}
.fb.funpl .fbar{background:repeating-linear-gradient(45deg,var(--late) 0 4px,var(--lates) 4px 8px)}.fb.funpl.done .fbar{background:var(--ok)}
@container (max-width:1100px){.bld{grid-template-columns:1fr}.todayc{position:static}.ntask{grid-template-columns:1fr 1fr}}
@container (max-width:820px){.xwin{padding:16px 14px}.qadd{flex-wrap:wrap}.qadd input{flex-basis:100%}.og,.og3{grid-template-columns:1fr}.og3 .oadd{grid-column:auto}.ugrid{grid-template-columns:1fr}.tcard{grid-template-columns:44px minmax(0,1fr) auto}.tcard .racts{grid-column:2/-1}.krrow{grid-template-columns:1fr}.ntask{grid-template-columns:1fr}}

/* KR picker, milestone chooser */
.kpick{padding:16px 18px;display:flex;flex-direction:column;gap:12px}
.kpg{display:grid;grid-template-columns:120px minmax(0,1fr);gap:12px;align-items:start}
.kpo{font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--gold2);padding-top:12px}
.kpr{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
.kpc{position:relative;display:flex;flex-direction:column;gap:8px;text-align:left;border:1px solid var(--line);background:var(--card);border-radius:12px;padding:11px 12px;font-size:13px;color:var(--ink2);line-height:1.35}
.kpc:hover{border-color:var(--gold)}
.kpc[aria-pressed="true"]{border-color:var(--ink);background:var(--goldsoft);color:var(--ink);box-shadow:inset 3px 0 0 var(--gold)}
.kpt b{font-family:var(--mono);font-size:12px;color:var(--ink);margin-right:4px}
.kpm{display:flex;gap:7px;align-items:center;flex-wrap:wrap;font-size:11.5px;color:var(--mut)}
.kpon{position:absolute;top:-9px;right:10px;background:var(--ink);color:var(--bg);font-size:10.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;border-radius:999px;padding:2px 8px}
.chooser{border-color:var(--crit);padding:16px 18px;display:flex;flex-direction:column;gap:10px}
.chh{display:flex;gap:12px;align-items:flex-start}.chh .ic{font-family:var(--serif);font-style:italic;color:var(--crit);font-size:22px;line-height:1}.chh>div{flex:1}.chh p{margin:4px 0 0}
.chr{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:10px;align-items:center}
.chr select{min-height:36px;border:1px solid var(--line);border-radius:10px;background:var(--card);padding:0 8px;color:var(--ink);width:100%}
.chr:not(.on) .msel{opacity:.85}
.chf{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;border-top:1px solid var(--line2);padding-top:10px}
[aria-disabled="true"]{opacity:.45}
@container (max-width:1100px){.kpr{grid-template-columns:1fr 1fr}}
@container (max-width:820px){.kpg{grid-template-columns:1fr}.kpo{padding-top:0}.kpr{grid-template-columns:1fr}.chr{grid-template-columns:1fr}}

/* carry-over window, week gate */
.carry{padding:12px 14px;display:flex;flex-direction:column;gap:10px;flex:none}
.carry.shut{padding-bottom:12px}
button.crhd{border:0;background:none;padding:0;width:100%;text-align:left;cursor:pointer;color:inherit}
.crcar{font-size:14px;color:var(--mut);width:16px;text-align:center;flex-shrink:0}
.carry .cra{flex-direction:column;align-items:stretch}.carry .cra select{width:100%}
.crhd{display:flex;gap:8px;align-items:flex-start;justify-content:space-between}.crhd>span:first-child{flex:1;min-width:0}.crhd b{display:block;font-size:14px}.crhd .note{display:block;font-size:11.5px}
.crsum{display:flex;gap:10px;flex-wrap:wrap;font-size:12px;color:var(--mut)}.crsum span{display:inline-flex;gap:5px;align-items:center}.crsum b{color:var(--ink)}
.crres{display:flex;gap:8px;align-items:center;font-size:12.5px;color:var(--ink2)}
.crl{display:flex;flex-direction:column;gap:8px}
.cri{border:1px solid var(--line);border-left:3px solid var(--ink);border-radius:10px;padding:8px 10px;display:flex;flex-direction:column;gap:4px;font-size:13px}
.cri.request{border-left-color:var(--info)}.cri.objective{border-left-color:var(--gold)}
.cri b{font-weight:600;line-height:1.3}
.crh{display:flex;gap:6px;align-items:center}.crt{font-size:10px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--gold2)}.crh2{margin-left:auto;font-size:12px;font-weight:600}
.cra{display:flex;gap:6px;flex-wrap:wrap;align-items:center}.cra select{min-height:30px;max-width:100%;flex:1;min-width:0;border:1px solid var(--line);border-radius:8px;background:var(--card);padding:0 6px;font-size:12px;color:var(--ink)}
.weekc{border-color:var(--ink)}
button.chk{border:0;cursor:pointer;font-family:inherit}
.gate{max-width:760px;margin:0 auto;border-color:var(--crit)}

/* weekly load */
table.wl td.wc{position:relative;min-width:58px;padding-bottom:14px}
table.wl td.wc i{position:absolute;left:10px;right:auto;bottom:6px;height:4px;border-radius:2px;background:var(--ok);max-width:calc(100% - 20px)}
table.wl td.wc.w i{background:var(--late)}table.wl td.wc.x i{background:var(--crit)}table.wl td.wc.x b{color:var(--crit)}table.wl td.wc.w b{color:var(--late)}

/* help counters */
.hstrip{display:flex;gap:16px;flex-wrap:wrap;align-items:baseline;border:1px solid var(--info);background:var(--infos);border-radius:12px;padding:9px 14px;font-size:13px;color:var(--ink2)}
.hstrip b{color:var(--info)}
.capbar.hl{height:6px}.capbar.hl i{background:var(--info)}
.hbar{display:inline-block;width:60px;height:5px;border-radius:3px;background:var(--soft);margin-left:8px;vertical-align:middle;overflow:hidden}.hbar i{display:block;height:100%;background:var(--info)}
#v-cockpit{display:flex;flex-direction:column;gap:16px}

.kpx{display:grid;grid-template-columns:200px minmax(0,1fr);gap:12px;align-items:end;border-top:1px solid var(--line2);padding-top:12px}.kpx>.pk{grid-column:1/-1}.kpx .chk{grid-column:1/-1;justify-self:start}
@container (max-width:820px){.kpx{grid-template-columns:1fr}}
.kpwarn{grid-column:1/-1;background:var(--lates);border-color:var(--late)}.kpwarn .ic{color:var(--late)}
/* tasks v2: readable, full width */
.tasks{padding:6px 0 4px}
.tk{display:grid;grid-template-columns:28px minmax(0,1fr);gap:10px;padding:12px 16px;border-top:1px solid var(--line2)}
.tk.bad{box-shadow:inset 3px 0 0 var(--crit)}
.tkn{width:26px;height:26px;border-radius:8px;background:var(--soft);display:grid;place-items:center;font:600 12px var(--mono);color:var(--mut);margin-top:3px}
.tkb{display:flex;flex-direction:column;gap:8px;min-width:0}
.tkt{width:100%;border:1px solid transparent;border-radius:8px;background:none;padding:4px 8px;margin-left:-8px;font-size:15.5px;font-weight:600;line-height:1.4;color:var(--ink);resize:none;overflow:hidden}
.tkt:hover{border-color:var(--line)}.tkt:focus{border-color:var(--gold);background:var(--card);outline:none}
.tkd{display:flex;align-items:center;gap:10px;font-size:12px;color:var(--mut)}
.tkd>span{white-space:nowrap;font-weight:600;letter-spacing:.04em;text-transform:uppercase;font-size:10.5px;color:var(--gold2)}
.tkd input{flex:1;min-width:0;min-height:34px;border:1px solid var(--line);border-radius:8px;background:var(--card);padding:0 10px;font-size:13.5px;color:var(--ink)}
.tkm{display:flex;align-items:center;gap:10px;flex-wrap:wrap}
.tko{display:inline-flex;align-items:center;gap:6px}
.tko select{min-height:30px;border:1px solid var(--line);border-radius:999px;background:var(--card);padding:0 8px;font-size:12.5px;color:var(--ink);max-width:130px}
.tkh{display:inline-flex;align-items:center;gap:2px;border:1px solid var(--line);border-radius:999px;padding:2px;background:var(--card);font-size:12.5px;color:var(--mut)}
.tkh input{width:44px;min-height:26px;border:0;background:none;text-align:center;font-family:var(--mono);font-size:13px;color:var(--ink);-moz-appearance:textfield}
.tkh input::-webkit-outer-spin-button,.tkh input::-webkit-inner-spin-button{-webkit-appearance:none;margin:0}
.stp{width:26px;height:26px;border-radius:50%;border:0;background:var(--soft);font-size:15px;line-height:1;color:var(--ink)}
.stp:hover{background:var(--ink);color:var(--bg)}
.tkm .checks{gap:4px}
.tasks .addrow{padding:10px 16px 12px 54px}

.ovr summary{cursor:pointer;font-size:12.5px;color:var(--mut);margin-top:4px}.ovr .oadd{margin-top:8px}
/* dialog, toast */
.scrim{position:fixed;inset:0;background:rgba(20,20,18,.5);display:flex;justify-content:center;align-items:flex-start;padding:40px max(16px,env(safe-area-inset-left,0px));overflow:auto;z-index:50}
.dlg{width:780px;max-width:100%;background:var(--card);border-radius:18px;border:1px solid var(--line)}
.dh{display:flex;gap:14px;align-items:flex-start;padding:20px 24px 14px;border-bottom:1px solid var(--line)}
