.kpl.on .kpb{background:var(--ink);border-color:var(--ink);color:#fff}
.kpn{border:0;background:none;text-align:left;cursor:pointer;min-width:0;display:flex;gap:6px;align-items:baseline;font:inherit;font-size:13px;color:var(--ink);padding:2px 0}
.kpn b{font-family:var(--mono);font-size:12px;flex-shrink:0}.kpn span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
